package vn.aujunpeak.assist;
import android.app.*;import android.content.*;import android.graphics.*;import android.hardware.display.*;import android.media.*;import android.media.projection.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;
public class CaptureService extends Service {
 MediaProjection projection;ImageReader reader;VirtualDisplay display;Handler h=new Handler(Looper.getMainLooper());boolean done;View toast;WindowManager wm;
 @Override public int onStartCommand(Intent i,int flags,int id){if(i==null||"STOP".equals(i.getAction())){stopSelf();return START_NOT_STICKY;}startForeground(22,OverlayService.notification(this,"Chụp một ảnh lưu trên máy",CaptureService.class));if(projection!=null)return START_NOT_STICKY;try{Intent data=i.getParcelableExtra("data");if(data==null){stopSelf();return START_NOT_STICKY;}projection=((MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE)).getMediaProjection(i.getIntExtra("code",-1),data);projection.registerCallback(new MediaProjection.Callback(){@Override public void onStop(){stopSelf();}},h);h.postDelayed(this::capture,3000);h.postDelayed(()->{if(!done){show("Chụp bị dừng hoặc hết thời gian",false);done=true;h.postDelayed(this::stopSelf,3000);}},12000);}catch(RuntimeException e){show("Không thể chụp màn hình",false);h.postDelayed(this::stopSelf,3000);}return START_NOT_STICKY;}
 void capture(){try{android.util.DisplayMetrics m=new android.util.DisplayMetrics();((WindowManager)getSystemService(WINDOW_SERVICE)).getDefaultDisplay().getRealMetrics(m);reader=ImageReader.newInstance(m.widthPixels,m.heightPixels,PixelFormat.RGBA_8888,2);reader.setOnImageAvailableListener(r->{if(done)return;try(Image image=r.acquireLatestImage()){if(image==null)return;done=true;Image.Plane plane=image.getPlanes()[0];int padding=plane.getRowStride()-plane.getPixelStride()*image.getWidth();Bitmap padded=Bitmap.createBitmap(image.getWidth()+padding/plane.getPixelStride(),image.getHeight(),Bitmap.Config.ARGB_8888);padded.copyPixelsFromBuffer(plane.getBuffer());Bitmap cropped=Bitmap.createBitmap(padded,0,0,image.getWidth(),image.getHeight());File dir=new File(getFilesDir(),"captures");if(!dir.exists()&&!dir.mkdirs())throw new IOException("mkdir");File out=new File(dir,"capture-"+System.currentTimeMillis()+".png");try(FileOutputStream stream=new FileOutputStream(out)){if(!cropped.compress(Bitmap.CompressFormat.PNG,100,stream))throw new IOException("encode");}if(cropped!=padded)cropped.recycle();padded.recycle();getSharedPreferences("assist",0).edit().putString("lastCapture",out.getAbsolutePath()).apply();show("✓ Đã lưu ảnh chụp",true);h.postDelayed(this::stopSelf,3000);}catch(Exception e){done=true;show("Không lưu được ảnh chụp",false);h.postDelayed(this::stopSelf,3000);}},h);display=projection.createVirtualDisplay("Single capture",m.widthPixels,m.heightPixels,m.densityDpi,DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,reader.getSurface(),null,h);}catch(RuntimeException e){done=true;show("Chụp màn hình thất bại",false);h.postDelayed(this::stopSelf,3000);}}
 void show(String message,boolean ok){wm=(WindowManager)getSystemService(WINDOW_SERVICE);TextView t=new TextView(this);t.setText(message);t.setTextSize(13);t.setTextColor(ok?0xff67edaa:Color.WHITE);t.setPadding(24,18,24,18);android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable();bg.setColor(0xf51b2521);bg.setCornerRadius(22);t.setBackground(bg);WindowManager.LayoutParams p=new WindowManager.LayoutParams(-2,-2,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE,PixelFormat.TRANSLUCENT);p.gravity=Gravity.TOP|Gravity.LEFT;p.y=80;try{wm.addView(t,p);toast=t;t.setAlpha(0);t.animate().alpha(1).setDuration(350).start();h.postDelayed(()->t.animate().alpha(0).setDuration(400).start(),2500);}catch(RuntimeException ignored){}}
 @Override public void onDestroy(){h.removeCallbacksAndMessages(null);if(display!=null)display.release();if(reader!=null)reader.close();if(projection!=null)projection.stop();if(toast!=null)try{wm.removeView(toast);}catch(RuntimeException ignored){}super.onDestroy();}@Override public IBinder onBind(Intent i){return null;}
}
